INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "郭言", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郭言。", "biography": null, "status": "draft", "id": "d890bf28-055c-53ab-a5fb-de04032e2f7b"}, {"name": "顾彦晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：顾彦晖。", "biography": null, "status": "draft", "id": "90e71b11-c2bf-56b5-872f-49a08caf734b"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "李继密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：李继密。", "biography": null, "status": "draft", "id": "27468166-8e95-5cdb-8b71-676673e9d18c"}, {"name": "徐彦若", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：徐彦若。", "biography": null, "status": "draft", "id": "bdcb2b2c-637f-5dfc-bfa9-bcd06621907d"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "王藏海", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：王藏海。", "biography": null, "status": "draft", "id": "9d4417c4-224f-53a3-8627-8b1daaa02d98"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "霍存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的霍存，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "ed410902-d5ba-5b58-8e3d-6d97034263e7"}, {"name": "朱友裕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：朱友裕。", "biography": null, "status": "draft", "id": "fd61394b-01c5-5bba-9d50-af1029c306bc"}, {"name": "李存孝", "aliases": ["安敬思"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存孝，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "时溥攻宿州，郭言战死", "start_year": 893, "end_year": 893, "time_original": "893年春正月；具体日未载", "dynasty": "唐", "description": "时溥遣军攻宿州，宿州刺史郭言战死。", "phases": [], "location_name": "宿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7edb6fed-d568-549e-9119-3bc11d221b55"}, {"title": "顾彦晖授东川节度使", "start_year": 893, "end_year": 893, "time_original": "893年正月条；具体日未载", "dynasty": "唐", "description": "顾彦晖与王建有隙，李茂贞想安抚使其依从自己，要求恢复赐节；朝廷诏授顾彦晖东川节度使。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0a361645-c5d8-562e-96ac-3334359eef04"}, {"title": "李茂贞奏遣李继密救梓州", "start_year": 893, "end_year": 893, "time_original": "893年正月条；具体日未载", "dynasty": "唐", "description": "李茂贞又奏请派知兴元府事李继密援救梓州。", "phases": [], "location_name": "梓州、兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "692d48d6-3bb3-5ed7-a862-6dc5ef3fcab8"}, {"title": "王建军在利州击败东川凤翔兵", "start_year": 893, "end_year": 893, "time_original": "未几；前述奏遣后不久", "dynasty": "唐", "description": "不久，王建遣军在利州击败东川与凤翔军队。", "phases": [], "location_name": "利州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e0f73ac1-522f-5c3d-9769-45260aeff17d"}, {"title": "顾彦晖求和，承诺与李茂贞断绝", "start_year": 893, "end_year": 893, "time_original": "利州兵败后；具体日未载", "dynasty": "唐", "description": "顾彦晖向王建求和，请与李茂贞断绝关系，王建同意。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "44036408-0ac7-51d1-a389-aeaf9da3235f"}, {"title": "李茂贞请镇兴元，授山南西道兼武定", "start_year": 893, "end_year": 893, "time_original": "893年正月条；具体日未载", "dynasty": "唐", "description": "李茂贞自请移镇兴元，朝廷任其为山南西道兼武定节度使。", "phases": [], "location_name": "兴元、山南西道、武定", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87c0a3d3-a755-5b04-96f5-3462d3934213"}, {"title": "徐彦若授凤翔，果阆划隶武定", "start_year": 893, "end_year": 893, "time_original": "893年正月条；具体日未载", "dynasty": "唐", "description": "朝廷任徐彦若同平章事、凤翔节度使，并划果州、阆州属武定军。", "phases": [], "location_name": "凤翔、果州、阆州、武定", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bc779e13-7f52-5d01-84e6-2a38c0f2bc7e"}, {"title": "李茂贞欲兼凤翔，不奉移镇诏", "start_year": 893, "end_year": 893, "time_original": "前述任命后；具体日未载", "dynasty": "唐", "description": "李茂贞想兼有凤翔，不遵奉朝廷移镇诏令。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "15ed7a94-f90d-5497-9fcb-74ab64230b3f"}, {"title": "王建加同平章事", "start_year": 893, "end_year": 893, "time_original": "893年二月甲戌", "dynasty": "唐", "description": "西川节度使王建加同平章事。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d5ee0cd7-d9ff-57b3-9ade-832ac1fb2a68"}, {"title": "李克用围邢，斩来信求解的王藏海", "start_year": 893, "end_year": 893, "time_original": "893年二月条；具体日未载", "dynasty": "唐", "description": "李克用率军围邢州，王镕派牙将王藏海带信请解围。李克用发怒，杀王藏海，并进兵攻王镕。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "23da6c70-6a9b-50a8-bd72-2c300a0d6b60"}, {"title": "李克用平山败镇兵，围天长旬日不下", "start_year": 893, "end_year": 893, "time_original": "893年二月辛巳攻天长；旬日不下", "dynasty": "唐", "description": "李克用在平山击败镇州军，辛巳进攻天长镇，十日未攻下。", "phases": [], "location_name": "平山、天长镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "15c712de-f77a-5f93-b9a4-0f7b1f377399"}, {"title": "王镕援天长，李克用叱日岭迎破", "start_year": 893, "end_year": 893, "time_original": "围天长旬日后条；具体日未载", "dynasty": "唐", "description": "王镕出兵三万救天长，李克用在叱日岭下迎战，大破援军，书载斩首万余级，其余军溃逃。", "phases": [], "location_name": "叱日岭、天长镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5a5ea87e-a27a-5055-bc58-3c2f19015315"}, {"title": "河东军缺粮，脯尸为食", "start_year": 893, "end_year": 893, "time_original": "叱日岭战后条；具体日未载", "dynasty": "唐", "description": "《通鉴》记河东军没有粮食，将死者尸体制成脯食用。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e5f4727c-d408-596d-acdc-b60909debc6a"}, {"title": "时溥求朱瑾援，霍存骑兵驻曹备之", "start_year": 893, "end_year": 893, "time_original": "893年二月条；具体日未载", "dynasty": "唐", "description": "时溥向朱瑾求援，朱全忠派霍存率三千骑兵驻曹州防备援军。", "phases": [], "location_name": "徐州、曹州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4caeb1f7-e2b0-5ff1-a585-f8783393a916"}, {"title": "霍存朱友裕石佛山下破徐兗兵", "start_year": 893, "end_year": 893, "time_original": "朱瑾率兵救徐之后；具体日未载", "dynasty": "唐", "description": "朱瑾率二万兵救徐州，霍存前往，与朱友裕合击徐州、兗州军于石佛山下，大破之，朱瑾逃回兗州。", "phases": [], "location_name": "石佛山、徐州、兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5298e21e-3a93-5a3f-a76d-d3eb1fbb268a"}, {"title": "徐兵再出，霍存战死", "start_year": 893, "end_year": 893, "time_original": "893年二月辛卯", "dynasty": "唐", "description": "徐州军再次出战，霍存战死。", "phases": [], "location_name": "徐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dc3098f6-c97c-5d66-add6-7c3aa293b5bf"}, {"title": "李克用下井陉，李存孝救王镕入镇议事", "start_year": 893, "end_year": 893, "time_original": "893年二月条；具体日未载", "dynasty": "唐", "description": "李克用攻下井陉。李存孝率兵救王镕，进入镇州同王镕商议。", "phases": [], "location_name": "井陉、镇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "893452b7-aaac-595b-a206-8d9455d57092"}, {"title": "王镕求朱援，朱全忠与李克用书信交锋", "start_year": 893, "end_year": 893, "time_original": "王镕求援后；具体日未载", "dynasty": "唐", "description": "王镕向朱全忠求援，朱正与时溥交战不能援，只写信向李克用声称邺下有十万精兵尚未进军。李克用回信说若确实驻邺下则盼降临，若要决胜负愿在常山之尾角逐。", "phases": [], "location_name": "邺下（朱函声称）、常山（李函约战）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "eacc3d33-c466-5b1b-aa60-be389933e27c"}, {"title": "李匡威元氏救王镕、李克用还邢", "start_year": 893, "end_year": 893, "time_original": "893年二月甲午", "dynasty": "唐", "description": "李匡威率兵援王镕，在元氏击败河东军，李克用退回邢州。", "phases": [], "location_name": "元氏、邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d9e59c6b-9f6b-5e43-8e26-61191468a2ec"}, {"title": "王镕藁城犒李匡威，以金帛酬援", "start_year": 893, "end_year": 893, "time_original": "元氏获援后；具体日未载", "dynasty": "唐", "description": "王镕在藁城犒劳李匡威，运送金帛二十万酬谢。", "phases": [], "location_name": "藁城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "498f8537-dd70-55b5-8e3c-b20304b83f24"}]'::jsonb)
